<?php
if(!defined('PANIC_ECO_ADMIN') || PANIC_ECO_ADMIN!==true) { http_response_code(403); exit; }
$account=$_GET['cuenta']??'';if(!is_string($account) || strlen($account)>50 || preg_match('/[\x00-\x1f]/',$account))throw new InvalidArgumentException('Revisá el nombre del jugador.');
$c=$ecoRepository->topupTotals();$p=$ecoRepository->topupTotals(true);$series=$ecoRepository->topupSeries();$rows=$ecoRepository->topupDetail($account);
panicEcoSentence('Entraron $ '.panicEcoNumber($c['Pesos']).' de '.panicEcoNumber($c['Recargas']).' recargas de '.panicEcoNumber($c['Cuentas']).' jugadores. Recarga promedio: $ '.panicEcoNumber($c['Ticket'],2).'.','Pesos reales que pagaron los jugadores por recargas. Si activaste mis pruebas, también se incluyen sus pagos de prueba.');
if((float)$c['Recargas']==0)panicEcoEmpty($ecoFilters['tests']);
echo '<div class="eco-metrics eco-metrics--three">';
panicEcoMetric('Plata que entró',$c['Pesos'],'Pesos reales que pagaron los jugadores por recargas.',['icon'=>'money','prefix'=>'$ ','flow'=>'in','comparison'=>panicEcoComparison($c['Pesos'],$p['Pesos'],panicEcoPeriodWords($ecoFilters))]);
panicEcoMetric('Recargas',$c['Recargas'],'Cantidad de recargas registradas en estas fechas. Un jugador puede haber recargado varias veces.',['icon'=>'coin','comparison'=>panicEcoComparison($c['Recargas'],$p['Recargas'],panicEcoPeriodWords($ecoFilters))]);
panicEcoMetric('Recarga promedio',$c['Ticket'],'Plata que entró dividida por la cantidad de recargas. Se expresa en pesos.',['icon'=>'money','prefix'=>'$ ','decimals'=>2,'comparison'=>panicEcoComparison($c['Ticket'],$p['Ticket'],panicEcoPeriodWords($ecoFilters))]);echo '</div>';
$unit=['dia'=>'día','semana'=>'semana','mes'=>'mes'][$ecoFilters['group']];panicEcoChart('Plata que entró por '.$unit,'bar',panicEcoCashRows($series),['Pesos'=>'Plata que entró · pesos'],['small'=>true]);
echo '<section class="eco-panel"><div class="eco-section-heading"><span class="eco-section-icon">'.panicEcoIcon('money').'</span><div><h3>Las últimas 10 recargas</h3><p>'.($account!==''?'Del jugador '.panicEcoEscape($account).'.':'Para ver de un vistazo quién recargó.').'</p></div></div>';
if(!$rows)echo '<p class="eco-note">Todavía no hay recargas para mostrar con estos filtros.</p>';else{echo '<ol class="eco-topup-list">';foreach(array_slice($rows,0,10) as $row)echo '<li><div><strong>'.panicEcoEscape($row['Cuenta']).'</strong><small>'.panicEcoEscape(panicEcoDate($row['FechaAR'])).((int)$row['Prueba']===1?' · Mis pruebas':'').'</small></div><div><strong class="eco-amount--in">▲ $ '.panicEcoNumber($row['Pesos'],2).'</strong><small>'.panicEcoNumber($row['Eryns']).' Eryns creados</small></div></li>';echo '</ol>';}echo '</section>';
panicEcoDetailStart('Buscar un jugador y ver todas las recargas cargadas', $account!=='');
?>
<form class="eco-filters eco-filters--small" method="get" action="<?php echo panicEcoEscape(__BASE_URL__.'usercp/shopadmin/'); ?>#economia"><?php foreach($ecoFilters['query'] as $key=>$value)echo '<input type="hidden" name="'.panicEcoEscape($key).'" value="'.panicEcoEscape($value).'">'; ?><label>Nombre exacto del jugador<input name="cuenta" maxlength="50" value="<?php echo panicEcoEscape($account); ?>" placeholder="Buscar en estas fechas"></label><button type="submit">Buscar jugador</button></form>
<?php
panicEcoTable('Últimas 1.000 recargas',['OrderID'=>'Número de compra','Proveedor'=>'Medio de pago','Ambiente'=>'Tipo de pago','Cuenta'=>'Jugador','Eryns'=>'Eryns creados','Pesos'=>'Plata que entró · pesos','FechaAR'=>'Cuándo · hora Argentina','Prueba'=>'Tipo de cuenta'],$rows,['numbers'=>['Eryns','Pesos'],'decimals'=>['Pesos'],'dates'=>['FechaAR'],'note'=>'La búsqueda por jugador se hace antes de cargar las últimas 1.000 filas. Las cifras de arriba corresponden a todas las recargas del rango, no solo al jugador buscado.']);
$aligned=[];$providers=[];foreach($series as $r){$key='p_'.hash('sha256',(string)$r['Proveedor']);$providers[$key]=(string)$r['Proveedor'];$k=$r['Periodo'];if(!isset($aligned[$k]))$aligned[$k]=['Periodo'=>$k];$aligned[$k][$key]=$r['Pesos'];}foreach($aligned as &$r)foreach($providers as $k=>$v)if(!isset($r[$k]))$r[$k]=0;unset($r);
panicEcoChart('Plata que entró por medio de pago','bar',array_values($aligned),$providers,['stacked'=>true]);panicEcoDetailEnd();
